ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'report.pdf';pdfmetrics.registerFont(TTFont('Snap',ROOT/'app/fonts/noto-sans-kr-regular.ttf'));pdfmetrics.registerFont(TTFont('SnapB',ROOT/'app/fonts/noto-sans-kr-bold.ttf'))
INK=colors.HexColor('#172b3a');BLUE=colors.HexColor('#176b87');SKY=colors.HexColor('#dff5f7');CREAM=colors.HexColor('#fff9ed');CORAL=colors.HexColor('#ff765f');MUTED=colors.HexColor('#60717a')
title=ParagraphStyle('t',fontName='SnapB',fontSize=29,leading=36,textColor=INK,spaceAfter=12);h1=ParagraphStyle('h1',fontName='SnapB',fontSize=20,leading=25,textColor=INK,spaceBefore=5,spaceAfter=10);h2=ParagraphStyle('h2',fontName='SnapB',fontSize=12,leading=17,textColor=BLUE,spaceBefore=9,spaceAfter=5);body=ParagraphStyle('b',fontName='Snap',fontSize=9.5,leading=15,textColor=INK,spaceAfter=7);small=ParagraphStyle('s',fontName='Snap',fontSize=8,leading=12,textColor=MUTED);center=ParagraphStyle('c',parent=body,alignment=TA_CENTER)
